import sys; sys.path.insert(0,'.')
from lib import *
P,y,ids,X = load_data(practice, tokenize, LABELS)
# bigram features via hashing pairs into dict
bg = {}
rows=[];cols=[]
for i,t in enumerate(ids):
    for a,b2 in zip(t[:-1],t[1:]):
        key=(a,b2)
        if key not in bg: bg[key]=len(bg)
        rows.append(i);cols.append(bg[key])
XB = sp.csr_matrix((np.ones(len(rows)),(rows,cols)),shape=(len(P),len(bg)))
XU = X[:, np.unique(X.indices)]
rng = np.random.RandomState(0); perm = rng.permutation(len(P)); folds = np.array_split(perm,5)
def nbcv(Xf, alpha=0.3, w=None):
    pred=np.zeros(len(P),int)
    Vf = Xf.shape[1]
    for f in folds:
        tr=np.setdiff1d(np.arange(len(P)),f)
        cnt=np.zeros((Vf,8))
        for c in range(8): cnt[:,c]=np.asarray(Xf[tr][y[tr]==c].sum(0)).ravel()
        lp=np.log(cnt+alpha)-np.log(cnt.sum(0)+alpha*Vf); lp-=lp.mean(1,keepdims=True)
        pred[f]=(Xf[f]@lp).argmax(1)
    return (pred==y).mean(), pred
for alpha in [0.1,0.3,1.0]:
    print('uni',alpha, nbcv(XU,alpha)[0], 'uni+bi', nbcv(sp.hstack([XU,XB]).tocsr(),alpha)[0])
acc,pred = nbcv(XU,0.3)
cm = np.zeros((8,8),int)
for a,b2 in zip(y,pred): cm[a,b2]+=1
print(LABELS); print(cm)
